import numpy as np
from scipy import stats

MAX_DRIVERS = 5

def design(feats):
    # Check if any feature shows strong association with outcome
    p_values = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] in ('clinical', 'cohort'):
            continue  # Skip clinical/cohort features for driver detection
        t_stat, p_val = stats.ttest_ind(feats.x[feats.y==1, i], feats.x[feats.y==0, i])
        p_values.append((p_val, fid))

    # Sort by p-value to find most significant features
    p_values.sort()

    # Look for potential drivers among clinical/cohort variables
    drivers = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] in ('clinical', 'cohort'):
            t_stat, p_val = stats.ttest_ind(feats.x[feats.y==1, i], feats.x[feats.y==0, i])
            if p_val < 0.05:
                drivers.append(fid)
                break  # Take the first significant clinical variable

    # If no driver found, return empty design
    if not drivers:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Select top 5 features with strong associations (p < 0.05)
    selected_features = []
    for p_val, fid in p_values[:10]:  # Top 10 features
        if p_val < 0.05:
            selected_features.append(fid)

    # Remove near-duplicates based on correlation > 0.6
    keep_features = set()

    # Check correlations between selected features
    for i, a in enumerate(selected_features):
        add_a = True
        for j, b in enumerate(selected_features[:i]):
            if (a, b) in keep_features or (b, a) in keep_features:
                continue
            corr = np.corrcoef(feats.x[:, feats.column(a)], feats.x[:, feats.column(b)])[0,1]
            if abs(corr) >= 0.6:
                # Keep the one with stronger effect size
                idx_a = feats.column(a)
                idx_b = feats.column(b)
                effect_a = abs(np.mean(feats.x[feats.y==1, idx_a]) - np.mean(feats.x[feats.y==0, idx_a]))
                effect_b = abs(np.mean(feats.x[feats.y==1, idx_b]) - np.mean(feats.x[feats.y==0, idx_b]))
                if effect_a >= effect_b:
                    keep_features.add(a)
                else:
                    keep_features.add(b)
                add_a = False
                break
        if add_a:
            keep_features.add(a)

    # Add remaining features to keep_features
    for f in selected_features:
        if f not in keep_features:
            keep_features.add(f)

    # Create products for top features
    products = []
    columns = tuple(keep_features)

    # Simple scoring: weighted sum of top features
    loadings = {}
    for fid in columns:
        idx = feats.column(fid)
        effect = np.mean(feats.x[feats.y==1, idx]) - np.mean(feats.x[feats.y==0, idx])
        loadings[fid] = effect

    # Limit to MAX_DRIVERS
    drivers = tuple(drivers[:MAX_DRIVERS])

    return Design(drivers=drivers, columns=columns, products=products, loadings=loadings)

